const e=JSON.parse(`[{"id":"upsc-2015-prelims-gs1-c-001","year":2015,"stage":"Prelims","paper":"Prelims GS-I","number":1,"booklet":"C","questionType":"MCQ","subject":"History","topic":"Cabinet Mission","question":"With reference to the Cabinet Mission, which of the following statements is/are correct?\\n\\n1. It recommended a federal government.\\n\\n2. It enlarged the powers of the Indian Courts.\\n\\n3. It provided for more Indians in the ICS.\\n\\nSelect the correct answer using the code given below.","options":{"a":"1 only","b":"2 and 3","c":"1 and 3","d":"None"},"answer":"a","keyStatus":"official","marks":2,"negativeMarks":0.6666666666666666,"wordLimit":0,"sourceUrl":"https://iasexamportal.com/ias-pre/papers/upsc-2015-gs-paper-1","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2015-GS-1.pdf#page=3","page":0,"blocks":[{"type":"paragraph","text":"With reference to the Cabinet Mission, which of the following statements is/are correct?"},{"type":"paragraph","text":"1. It recommended a federal government."},{"type":"paragraph","text":"2. It enlarged the powers of the Indian Courts."},{"type":"paragraph","text":"3. It provided for more Indians in the ICS."},{"type":"paragraph","text":"Select the correct answer using the code given below."}],"sourceTitle":"UPSC CSE 2015 General Studies Paper I · Series C","explanation":{"justification":"The 1946 Cabinet Mission proposed a federal union with limited central subjects. Enlarging court powers and increasing Indian recruitment to the ICS were not features of its plan. Only statement 1 is correct.","concept":"Cabinet Mission","references":[{"title":"UPSC CSE2015 final key · SeriesC","url":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2015-GS-1.pdf#page=3"}]},"sourceNotes":"Editorial study note checked against the final key’s correct option; UPSC publishes the answer key, not these explanations."},{"id":"upsc-2015-prelims-gs1-c-002","year":2015,"stage":"Prelims","paper":"Prelims GS-I","number":2,"booklet":"C","questionType":"MCQ","subject":"Environment","topic":"Climate action & agreements","question":"Which one of the following National Parks has a climate that varies from tropical to subtropical, temperate and arctic?","options":{"a":"Khangchendzonga National Park","b":"Nandadevi National Park","c":"Neora Valley National Park","d":"Namdapha National Park"},"answer":"d","keyStatus":"official","marks":2,"negativeMarks":0.6666666666666666,"wordLimit":0,"sourceUrl":"https://iasexamportal.com/ias-pre/papers/upsc-2015-gs-paper-1","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2015-GS-1.pdf#page=3","page":0,"blocks":[{"type":"paragraph","text":"Which one of the following National Parks has a climate that varies from tropical to subtropical, temperate and arctic?"}],"sourceTitle":"UPSC CSE 2015 General Studies Paper I · Series C","explanation":{"justification":"Namdapha National Park in Arunachal Pradesh exhibits an extraordinary altitudinal variation, causing its climate and biomes to range dramatically from tropical evergreen rainforests in the lowlands to temperate and finally arctic (alpine) conditions at the highest peaks.","concept":"","references":[]},"sourceNotes":"Editorial study note matched by question wording and the final key’s correct-option wording; the UPSC final key controls scoring."},{"id":"upsc-2015-prelims-gs1-c-003","year":2015,"stage":"Prelims","paper":"Prelims GS-I","number":3,"booklet":"C","questionType":"MCQ","subject":"International Relations","topic":"Human rights organisations","question":"Amnesty International is","options":{"a":"an agency of the United Nations to help refugees of civil wars","b":"a global Human Rights Movement","c":"a non-governmental voluntary organization to help very poor people","d":"an inter-governmental agency to cater to medical emergencies in war-ravaged regions"},"answer":"b","keyStatus":"official","marks":2,"negativeMarks":0.6666666666666666,"wordLimit":0,"sourceUrl":"https://iasexamportal.com/ias-pre/papers/upsc-2015-gs-paper-1","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2015-GS-1.pdf#page=3","page":0,"blocks":[{"type":"paragraph","text":"Amnesty International is"}],"sourceTitle":"UPSC CSE 2015 General Studies Paper I · Series C","explanation":{"justification":"Amnesty International is an independent global movement that campaigns for human rights. It is neither a United Nations agency nor an intergovernmental organisation.","concept":"Human rights organisations","references":[{"title":"UPSC CSE2015 final key · SeriesC","url":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2015-GS-1.pdf#page=3"}]},"sourceNotes":"Editorial study note checked against the final key’s correct option; UPSC publishes the answer key, not these explanations."},{"id":"upsc-2015-prelims-gs1-c-004","year":2015,"stage":"Prelims","paper":"Prelims GS-I","number":4,"booklet":"C","questionType":"MCQ","subject":"Art & Culture","topic":"Art, architecture & monuments","question":"With reference to the art and archaeological history of India, which one among the following was made earliest?","options":{"a":"Lingaraja Temple at Bhubaneswar","b":"Rock-cut Elephant at Dhauli","c":"Rock-cut Monuments at Mahabalipuram","d":"varaha Image at Udayagiri"},"answer":"b","keyStatus":"official","marks":2,"negativeMarks":0.6666666666666666,"wordLimit":0,"sourceUrl":"https://iasexamportal.com/ias-pre/papers/upsc-2015-gs-paper-1","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2015-GS-1.pdf#page=3","page":0,"blocks":[{"type":"paragraph","text":"With reference to the art and archaeological history of India, which one among the following was made earliest?"}],"sourceTitle":"UPSC CSE 2015 General Studies Paper I · Series C","explanation":{"justification":"The Rock-cut Elephant at Dhauli (Odisha) was sculpted during the reign of Mauryan Emperor Ashoka in the 3rd century BCE, making it the earliest among the given options. The Varaha image dates to 5th century CE (Gupta period), Mahabalipuram to 7th century CE (Pallava period), and Lingaraja temple to 11th century CE.","concept":"","references":[]},"sourceNotes":"Editorial study note matched by question wording and the final key’s correct-option wording; the UPSC final key controls scoring."},{"id":"upsc-2015-prelims-gs1-c-005","year":2015,"stage":"Prelims","paper":"Prelims GS-I","number":5,"booklet":"C","questionType":"MCQ","subject":"History","topic":"Feudalism","question":"With reference to Indian history, which of the following is/are the essential element/elements of the feudal system?\\n\\n1. A very strong centralized political authority and a very weak provincial or local political authority\\n\\n2. Emergence of administrative structure based on control and possession of land\\n\\n3. Creation of lord-vassal relationship between the feudal lord and his overlord\\n\\nSelect the correct answer using the code given below.","options":{"a":"1 and 2 only","b":"2 and 3 only","c":"3 only","d":"1, 2 and 3"},"answer":"b","keyStatus":"official","marks":2,"negativeMarks":0.6666666666666666,"wordLimit":0,"sourceUrl":"https://iasexamportal.com/ias-pre/papers/upsc-2015-gs-paper-1","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2015-GS-1.pdf#page=3","page":0,"blocks":[{"type":"paragraph","text":"With reference to Indian history, which of the following is/are the essential element/elements of the feudal system?"},{"type":"paragraph","text":"1. A very strong centralized political authority and a very weak provincial or local political authority"},{"type":"paragraph","text":"2. Emergence of administrative structure based on control and possession of land"},{"type":"paragraph","text":"3. Creation of lord-vassal relationship between the feudal lord and his overlord"},{"type":"paragraph","text":"Select the correct answer using the code given below."}],"sourceTitle":"UPSC CSE 2015 General Studies Paper I · Series C","explanation":{"justification":"Feudal arrangements rested on control of land and obligations between lords and vassals. They involved dispersed authority rather than a very strong central government. Statements 2 and 3 are correct.","concept":"Feudalism","references":[{"title":"UPSC CSE2015 final key · SeriesC","url":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2015-GS-1.pdf#page=3"}]},"sourceNotes":"Editorial study note checked against the final key’s correct option; UPSC publishes the answer key, not these explanations."},{"id":"upsc-2015-prelims-gs1-c-006","year":2015,"stage":"Prelims","paper":"Prelims GS-I","number":6,"booklet":"C","questionType":"MCQ","subject":"Environment","topic":"Climate action & agreements","question":"'BioCarbon Fund Initiative for Sustainable Forest Landscapes' is managed by the","options":{"a":"Asian Development Bank","b":"International Monetary Fund","c":"United Nations Environment Programme","d":"World Bank"},"answer":"d","keyStatus":"official","marks":2,"negativeMarks":0.6666666666666666,"wordLimit":0,"sourceUrl":"https://iasexamportal.com/ias-pre/papers/upsc-2015-gs-paper-1","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2015-GS-1.pdf#page=3","page":0,"blocks":[{"type":"paragraph","text":"'BioCarbon Fund Initiative for Sustainable Forest Landscapes' is managed by the"}],"sourceTitle":"UPSC CSE 2015 General Studies Paper I · Series C","explanation":{"justification":"The BioCarbon Fund Initiative for Sustainable Forest Landscapes (ISFL) is a multilateral fund managed by the World Bank to promote and reward reduced greenhouse gas emissions from the land sector, including from deforestation and forest degradation.","concept":"","references":[]},"sourceNotes":"Editorial study note matched by question wording and the final key’s correct-option wording; the UPSC final key controls scoring."},{"id":"upsc-2015-prelims-gs1-c-007","year":2015,"stage":"Prelims","paper":"Prelims GS-I","number":7,"booklet":"C","questionType":"MCQ","subject":"International Relations","topic":"Regional organisations","question":"India is a member of which among the following?\\n\\n1. Asia-Pacific Economic Cooperation\\n\\n2. Association of South-East Asian Nations\\n\\n3. East Asia Summit\\n\\nSelect the correct answer using the code given below.","options":{"a":"1 and 2 only","b":"3 only","c":"1, 2 and 3","d":"India is a member of none of them"},"answer":"b","keyStatus":"official","marks":2,"negativeMarks":0.6666666666666666,"wordLimit":0,"sourceUrl":"https://iasexamportal.com/ias-pre/papers/upsc-2015-gs-paper-1","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2015-GS-1.pdf#page=3","page":0,"blocks":[{"type":"paragraph","text":"India is a member of which among the following?"},{"type":"paragraph","text":"1. Asia-Pacific Economic Cooperation"},{"type":"paragraph","text":"2. Association of South-East Asian Nations"},{"type":"paragraph","text":"3. East Asia Summit"},{"type":"paragraph","text":"Select the correct answer using the code given below."}],"sourceTitle":"UPSC CSE 2015 General Studies Paper I · Series C","explanation":{"justification":"At the time of the 2015 examination India was a participant in the East Asia Summit, but was not a member of either APEC or ASEAN. Only item 3 applies.","concept":"Regional organisations","references":[{"title":"UPSC CSE2015 final key · SeriesC","url":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2015-GS-1.pdf#page=3"}]},"sourceNotes":"Editorial study note checked against the final key’s correct option; UPSC publishes the answer key, not these explanations."},{"id":"upsc-2015-prelims-gs1-c-008","year":2015,"stage":"Prelims","paper":"Prelims GS-I","number":8,"booklet":"C","questionType":"MCQ","subject":"Economy","topic":"Steel industry","question":"In India, the steel production industry requires the import of","options":{"a":"saltpetre","b":"rock phosphate","c":"coking coal","d":"All of the above"},"answer":"c","keyStatus":"official","marks":2,"negativeMarks":0.6666666666666666,"wordLimit":0,"sourceUrl":"https://iasexamportal.com/ias-pre/papers/upsc-2015-gs-paper-1","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2015-GS-1.pdf#page=3","page":0,"blocks":[{"type":"paragraph","text":"In India, the steel production industry requires the import of"}],"sourceTitle":"UPSC CSE 2015 General Studies Paper I · Series C","explanation":{"justification":"Steelmaking needs metallurgical or coking coal to produce coke for blast furnaces. Indian production does not meet the industry’s requirements in quantity and quality, making imports necessary.","concept":"Steel industry","references":[{"title":"UPSC CSE2015 final key · SeriesC","url":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2015-GS-1.pdf#page=3"}]},"sourceNotes":"Editorial study note checked against the final key’s correct option; UPSC publishes the answer key, not these explanations."},{"id":"upsc-2015-prelims-gs1-c-009","year":2015,"stage":"Prelims","paper":"Prelims GS-I","number":9,"booklet":"C","questionType":"MCQ","subject":"Polity & Governance","topic":"Constitutional history & foundations","question":"The provisions in Fifth Schedule and Sixth Schedule in the Constitution of India are made in order to","options":{"a":"protect the interests of Scheduled Tribes","b":"determine the boundaries between States","c":"determine the powers, authority and responsibilities of Panchayats","d":"protect the interests of all the border States"},"answer":"a","keyStatus":"official","marks":2,"negativeMarks":0.6666666666666666,"wordLimit":0,"sourceUrl":"https://iasexamportal.com/ias-pre/papers/upsc-2015-gs-paper-1","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2015-GS-1.pdf#page=3","page":0,"blocks":[{"type":"paragraph","text":"The provisions in Fifth Schedule and Sixth Schedule in the Constitution of India are made in order to"}],"sourceTitle":"UPSC CSE 2015 General Studies Paper I · Series C","explanation":{"justification":"Both the Fifth and Sixth Schedules aim to protect the interests and socio-cultural identity of Scheduled Tribes by providing special administration structures for scheduled and tribal areas.","concept":"","references":[]},"sourceNotes":"Editorial study note matched by question wording and the final key’s correct-option wording; the UPSC final key controls scoring."},{"id":"upsc-2015-prelims-gs1-c-010","year":2015,"stage":"Prelims","paper":"Prelims GS-I","number":10,"booklet":"C","questionType":"MCQ","subject":"Polity & Governance","topic":"Parliament & state legislatures","question":"With reference to the Union Government, consider the following statements :\\n\\n1. The Department of Revenue is responsible for the preparation of Union Budget that is presented to the Parliament.\\n\\n2. No amount can be withdrawn from the Consolidated Fund of India without the authorization from the\\n\\nParliament of India.\\n\\n3. All the disbursements made from Public Account also need the authorization from the Parliament of India.\\n\\nWhich of the statements given above is / are correct?","options":{"a":"1 and 2 only","b":"2 and 3 only","c":"2 only","d":"1, 2 and 3"},"answer":"c","keyStatus":"official","marks":2,"negativeMarks":0.6666666666666666,"wordLimit":0,"sourceUrl":"https://iasexamportal.com/ias-pre/papers/upsc-2015-gs-paper-1","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2015-GS-1.pdf#page=3","page":0,"blocks":[{"type":"paragraph","text":"With reference to the Union Government, consider the following statements :"},{"type":"paragraph","text":"1. The Department of Revenue is responsible for the preparation of Union Budget that is presented to the Parliament."},{"type":"paragraph","text":"2. No amount can be withdrawn from the Consolidated Fund of India without the authorization from the\\n\\nParliament of India."},{"type":"paragraph","text":"3. All the disbursements made from Public Account also need the authorization from the Parliament of India."},{"type":"paragraph","text":"Which of the statements given above is / are correct?"}],"sourceTitle":"UPSC CSE 2015 General Studies Paper I · Series C","explanation":{"justification":"The Department of Economic Affairs (not Revenue) prepares the budget (Statement 1 is incorrect). Parliamentary authorization is required to withdraw from the Consolidated Fund (Statement 2 is correct). Disbursements from the Public Account can be made by executive action without parliamentary appropriation (Statement 3 is incorrect).","concept":"","references":[]},"sourceNotes":"Editorial study note matched by question wording and the final key’s correct-option wording; the UPSC final key controls scoring."},{"id":"upsc-2015-prelims-gs1-c-011","year":2015,"stage":"Prelims","paper":"Prelims GS-I","number":11,"booklet":"C","questionType":"MCQ","subject":"Polity & Governance","topic":"Judiciary","question":"Who /Which of the following is the custodian of the Constitution of India?","options":{"a":"The President of India","b":"The Prime Minister of India","c":"The Lok Sabha Secretariat","d":"The Supreme court of India"},"answer":"d","keyStatus":"official","marks":2,"negativeMarks":0.6666666666666666,"wordLimit":0,"sourceUrl":"https://iasexamportal.com/ias-pre/papers/upsc-2015-gs-paper-1","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2015-GS-1.pdf#page=3","page":0,"blocks":[{"type":"paragraph","text":"Who /Which of the following is the custodian of the Constitution of India?"}],"sourceTitle":"UPSC CSE 2015 General Studies Paper I · Series C","explanation":{"justification":"The Supreme Court is the final interpreter and guardian/custodian of the Constitution and guarantor of the fundamental rights of the citizens.","concept":"","references":[]},"sourceNotes":"Editorial study note matched by question wording and the final key’s correct-option wording; the UPSC final key controls scoring."},{"id":"upsc-2015-prelims-gs1-c-012","year":2015,"stage":"Prelims","paper":"Prelims GS-I","number":12,"booklet":"C","questionType":"MCQ","subject":"Economy","topic":"Agriculture & allied sectors","question":"Consider the following statements:\\n\\n1. The Accelerated Irrigation Benefits Programme was launched during 1996-97 to provide loan assistance to poor farmers.\\n\\n2. The Command Area Development Programme was launched in 1974-75 for the development of water-use efficiency.\\n\\nWhich of the statements given above is/are correct?","options":{"a":"1 only","b":"2 only","c":"Both 1 and 2","d":"Neither 1 nor 2"},"answer":"b","keyStatus":"official","marks":2,"negativeMarks":0.6666666666666666,"wordLimit":0,"sourceUrl":"https://iasexamportal.com/ias-pre/papers/upsc-2015-gs-paper-1","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2015-GS-1.pdf#page=3","page":0,"blocks":[{"type":"paragraph","text":"Consider the following statements:"},{"type":"paragraph","text":"1. The Accelerated Irrigation Benefits Programme was launched during 1996-97 to provide loan assistance to poor farmers."},{"type":"paragraph","text":"2. The Command Area Development Programme was launched in 1974-75 for the development of water-use efficiency.\\n\\nWhich of the statements given above is/are correct?"}],"sourceTitle":"UPSC CSE 2015 General Studies Paper I · Series C","explanation":{"justification":"Statement 1 is incorrect because the AIBP (launched in 1996-97) provides Central Loan Assistance to state governments to speed up the completion of major/medium irrigation projects, not direct loan assistance to poor farmers. Statement 2 is correct, as CADP was introduced in 1974-75 specifically to bridge the gap between irrigation potential created and utilized, thereby improving water-use efficiency.","concept":"","references":[]},"sourceNotes":"Editorial study note matched by question wording and the final key’s correct-option wording; the UPSC final key controls scoring."},{"id":"upsc-2015-prelims-gs1-c-013","year":2015,"stage":"Prelims","paper":"Prelims GS-I","number":13,"booklet":"C","questionType":"MCQ","subject":"Environment","topic":"Climate action & agreements","question":"The Genetic Engineering Appraisal Committee is constituted under the","options":{"a":"Food Safety and Standards Act, 2006","b":"Geographical Indications of Goods (Registration and Protection) Act, 1999","c":"Environment (Protection) Act, 1986","d":"Wildlife (Protection) Act, 1972"},"answer":"c","keyStatus":"official","marks":2,"negativeMarks":0.6666666666666666,"wordLimit":0,"sourceUrl":"https://iasexamportal.com/ias-pre/papers/upsc-2015-gs-paper-1","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2015-GS-1.pdf#page=3","page":0,"blocks":[{"type":"paragraph","text":"The Genetic Engineering Appraisal Committee is constituted under the"}],"sourceTitle":"UPSC CSE 2015 General Studies Paper I · Series C","explanation":{"justification":"The Genetic Engineering Appraisal Committee (GEAC), which functions under the Ministry of Environment, Forest and Climate Change, was constituted under the Environment (Protection) Act, 1986 to appraise activities involving hazardous microorganisms and recombinant DNA.","concept":"","references":[]},"sourceNotes":"Editorial study note matched by question wording and the final key’s correct-option wording; the UPSC final key controls scoring."},{"id":"upsc-2015-prelims-gs1-c-014","year":2015,"stage":"Prelims","paper":"Prelims GS-I","number":14,"booklet":"C","questionType":"MCQ","subject":"International Relations","topic":"Mekong-Ganga Cooperation","question":"In the Mekong-Ganga Cooperation, an initiative of six countries, which of the following is/are not a participant/ participants?\\n\\n1. Bangladesh\\n\\n2. Cambodia\\n\\n3. China\\n\\n4. Myanmar\\n\\n5. Thailand\\n\\nSelect the correct answer using the code given below.","options":{"a":"1 only","b":"2, 3 and 4","c":"1 and 3","d":"1, 2 and 5"},"answer":"c","keyStatus":"official","marks":2,"negativeMarks":0.6666666666666666,"wordLimit":0,"sourceUrl":"https://iasexamportal.com/ias-pre/papers/upsc-2015-gs-paper-1","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2015-GS-1.pdf#page=3","page":0,"blocks":[{"type":"paragraph","text":"In the Mekong-Ganga Cooperation, an initiative of six countries, which of the following is/are not a participant/ participants?"},{"type":"paragraph","text":"1. Bangladesh"},{"type":"paragraph","text":"2. Cambodia"},{"type":"paragraph","text":"3. China"},{"type":"paragraph","text":"4. Myanmar"},{"type":"paragraph","text":"5. Thailand"},{"type":"paragraph","text":"Select the correct answer using the code given below."}],"sourceTitle":"UPSC CSE 2015 General Studies Paper I · Series C","explanation":{"justification":"The six members are India, Cambodia, Laos, Myanmar, Thailand and Vietnam. Bangladesh and China are outside the grouping, so items 1 and 3 are the correct exclusions.","concept":"Mekong-Ganga Cooperation","references":[{"title":"UPSC CSE2015 final key · SeriesC","url":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2015-GS-1.pdf#page=3"}]},"sourceNotes":"Editorial study note checked against the final key’s correct option; UPSC publishes the answer key, not these explanations."},{"id":"upsc-2015-prelims-gs1-c-015","year":2015,"stage":"Prelims","paper":"Prelims GS-I","number":15,"booklet":"C","questionType":"MCQ","subject":"Economy","topic":"Banking, money & financial markets","question":"'Basel III Accord' or simply 'Basel III', often seen in the news, seeks to","options":{"a":"develop national strategies for the conservation and sustainable use of biological diversity","b":"improve banking sector's ability to deal with financial and economic stress and improve risk management","c":"reduce the greenhouse gas emissions but places a heavier burden on developed countries","d":"transfer technology from developed Countries to poor countries to enable them to replace the use of chlorofluorocarbons in refrigeration with harmless chemicals"},"answer":"b","keyStatus":"official","marks":2,"negativeMarks":0.6666666666666666,"wordLimit":0,"sourceUrl":"https://iasexamportal.com/ias-pre/papers/upsc-2015-gs-paper-1","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2015-GS-1.pdf#page=3","page":0,"blocks":[{"type":"paragraph","text":"'Basel III Accord' or simply 'Basel III', often seen in the news, seeks to"}],"sourceTitle":"UPSC CSE 2015 General Studies Paper I · Series C","explanation":{"justification":"Basel III is a comprehensive set of international banking regulations developed by the Bank for International Settlements (BIS) to strengthen bank capital requirements, increase liquidity buffers, and improve the banking sector's resilience and risk management against financial and economic stress.","concept":"","references":[]},"sourceNotes":"Editorial study note matched by question wording and the final key’s correct-option wording; the UPSC final key controls scoring."},{"id":"upsc-2015-prelims-gs1-c-016","year":2015,"stage":"Prelims","paper":"Prelims GS-I","number":16,"booklet":"C","questionType":"MCQ","subject":"Geography","topic":"Climatology","question":"Consider the following statements\\n\\n1. The winds which blow between 30o N and 60o S latitudes throughout the year are known as westerlies.\\n\\n2. The moist air masses that cause winter rains in North-Western region of India are part of westerlies.\\n\\nWhich of the statements given above is/are correct?","options":{"a":"1 only","b":"2 only","c":"Both 1 and 2","d":"Neither 1 nor 2"},"answer":"b","keyStatus":"official","marks":2,"negativeMarks":0.6666666666666666,"wordLimit":0,"sourceUrl":"https://iasexamportal.com/ias-pre/papers/upsc-2015-gs-paper-1","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2015-GS-1.pdf#page=3","page":0,"blocks":[{"type":"paragraph","text":"Consider the following statements"},{"type":"paragraph","text":"1. The winds which blow between 30o N and 60o S latitudes throughout the year are known as westerlies."},{"type":"paragraph","text":"2. The moist air masses that cause winter rains in North-Western region of India are part of westerlies.\\n\\nWhich of the statements given above is/are correct?"}],"sourceTitle":"UPSC CSE 2015 General Studies Paper I · Series C","explanation":{"justification":"Statement 1 is incorrect as Westerlies blow between 30° and 60° latitudes in *both* hemispheres (30°N to 60°N and 30°S to 60°S).","concept":"","references":[]},"sourceNotes":"Editorial study note matched by question wording and the final key’s correct-option wording; the UPSC final key controls scoring."},{"id":"upsc-2015-prelims-gs1-c-017","year":2015,"stage":"Prelims","paper":"Prelims GS-I","number":17,"booklet":"C","questionType":"MCQ","subject":"International Relations","topic":"Indian Ocean Rim Association","question":"With reference to 'Indian Ocean Rim Association for Regional Cooperation (IOR-ARC)', consider the following statements:\\n\\n1. It was established very recently in response to incidents of piracy and accidents of oil spills.\\n\\n2. It is an alliance meant for maritime security only.\\n\\nWhich of the statements given above is / are correct?","options":{"a":"1 only","b":"2 only","c":"Both 1 and 2","d":"Neither 1 nor 2"},"answer":"d","keyStatus":"official","marks":2,"negativeMarks":0.6666666666666666,"wordLimit":0,"sourceUrl":"https://iasexamportal.com/ias-pre/papers/upsc-2015-gs-paper-1","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2015-GS-1.pdf#page=3","page":0,"blocks":[{"type":"paragraph","text":"With reference to 'Indian Ocean Rim Association for Regional Cooperation (IOR-ARC)', consider the following statements:"},{"type":"paragraph","text":"1. It was established very recently in response to incidents of piracy and accidents of oil spills."},{"type":"paragraph","text":"2. It is an alliance meant for maritime security only.\\n\\nWhich of the statements given above is / are correct?"}],"sourceTitle":"UPSC CSE 2015 General Studies Paper I · Series C","explanation":{"justification":"IOR-ARC was established in 1997 and covers economic cooperation, trade and other regional priorities, alongside maritime matters. It was not a newly created organisation restricted to security.","concept":"Indian Ocean Rim Association","references":[{"title":"UPSC CSE2015 final key · SeriesC","url":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2015-GS-1.pdf#page=3"}]},"sourceNotes":"Editorial study note checked against the final key’s correct option; UPSC publishes the answer key, not these explanations."},{"id":"upsc-2015-prelims-gs1-c-018","year":2015,"stage":"Prelims","paper":"Prelims GS-I","number":18,"booklet":"C","questionType":"MCQ","subject":"History","topic":"Modern India · nationalism & revolutionary movements","question":"Which one of the following movements has contributed to a split in the Indian National Congress resulting in the emergence of 'moderates' and 'extremists'?","options":{"a":"Swadeshi Movement","b":"Quit India Movement","c":"Non-Cooperation Movement","d":"Civil Disobedience Movement"},"answer":"a","keyStatus":"official","marks":2,"negativeMarks":0.6666666666666666,"wordLimit":0,"sourceUrl":"https://iasexamportal.com/ias-pre/papers/upsc-2015-gs-paper-1","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2015-GS-1.pdf#page=3","page":0,"blocks":[{"type":"paragraph","text":"Which one of the following movements has contributed to a split in the Indian National Congress resulting in the emergence of 'moderates' and 'extremists'?"}],"sourceTitle":"UPSC CSE 2015 General Studies Paper I · Series C","explanation":{"justification":"The ideological and methodological differences regarding the pace and methods of the Swadeshi Movement (1905) led to the Surat Split in 1907 between the Moderates and the Extremists.","concept":"","references":[]},"sourceNotes":"Editorial study note matched by question wording and the final key’s correct-option wording; the UPSC final key controls scoring."},{"id":"upsc-2015-prelims-gs1-c-019","year":2015,"stage":"Prelims","paper":"Prelims GS-I","number":19,"booklet":"C","questionType":"MCQ","subject":"Geography","topic":"India Physical Environment","question":"In a particular region in India, the local people train the roots of living trees into robust bridges across the streams. As the time passes, these bridges become stronger. These unique 'living root bridges' are found in","options":{"a":"Meghalaya","b":"Himachal Pradesh","c":"Jharkhand","d":"Tamil Nadu"},"answer":"a","keyStatus":"official","marks":2,"negativeMarks":0.6666666666666666,"wordLimit":0,"sourceUrl":"https://iasexamportal.com/ias-pre/papers/upsc-2015-gs-paper-1","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2015-GS-1.pdf#page=3","page":0,"blocks":[{"type":"paragraph","text":"In a particular region in India, the local people train the roots of living trees into robust bridges across the streams. As the time passes, these bridges become stronger. These unique 'living root bridges' are found in"}],"sourceTitle":"UPSC CSE 2015 General Studies Paper I · Series C","explanation":{"justification":"The jing kiengjri or living root bridges — aerial bridges built by weaving and manipulating the roots of the Indian rubber tree — have been serving as connectors for generations in Meghalaya. Spanning between 15 and 250 feet and built over centuries, the bridges, primarily a means to cross streams and rivers, have also become world-famous tourist attractions.","concept":"India Physical Environment","references":[]},"sourceNotes":"Editorial study note matched by question wording and the final key’s correct-option wording; the UPSC final key controls scoring."},{"id":"upsc-2015-prelims-gs1-c-020","year":2015,"stage":"Prelims","paper":"Prelims GS-I","number":20,"booklet":"C","questionType":"MCQ","subject":"Geography","topic":"Oceanography","question":"Tides occur in the oceans and seas due to which among the following?\\n\\n1. Gravitational force of the Sun\\n\\n2. Gravitational force of the Moon\\n\\n3. Centrifugal force of the Earth\\n\\nSelect the correct answer using the code given below.","options":{"a":"1 only","b":"2 and 3 only","c":"1 and 3 only","d":"1, 2 and 3"},"answer":"d","keyStatus":"official","marks":2,"negativeMarks":0.6666666666666666,"wordLimit":0,"sourceUrl":"https://iasexamportal.com/ias-pre/papers/upsc-2015-gs-paper-1","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2015-GS-1.pdf#page=3","page":0,"blocks":[{"type":"paragraph","text":"Tides occur in the oceans and seas due to which among the following?"},{"type":"paragraph","text":"1. Gravitational force of the Sun"},{"type":"paragraph","text":"2. Gravitational force of the Moon"},{"type":"paragraph","text":"3. Centrifugal force of the Earth"},{"type":"paragraph","text":"Select the correct answer using the code given below."}],"sourceTitle":"UPSC CSE 2015 General Studies Paper I · Series C","explanation":{"justification":"Tides are the rise and fall of sea levels caused by the combined effects of the gravitational forces exerted by the moon and the sun, and the centrifugal force due to the rotation of the earth.","concept":"","references":[]},"sourceNotes":"Editorial study note matched by question wording and the final key’s correct-option wording; the UPSC final key controls scoring."},{"id":"upsc-2015-prelims-gs1-c-021","year":2015,"stage":"Prelims","paper":"Prelims GS-I","number":21,"booklet":"C","questionType":"MCQ","subject":"Geography","topic":"Indian geography & resources","question":"In which of the following activities are Indian Remote Sensing (IRS) satellites used?\\n\\n1. Assessment of crop productivity\\n\\n2. Locating groundwater resources\\n\\n3. Mineral exploration\\n\\n4. Telecommunications\\n\\n5. Traffic studies\\n\\nSelect the correct answer using the code given below.","options":{"a":"1, 2 and 3 only","b":"4 and 5 only","c":"1 and 2 only","d":"1, 2, 3, 4 and 5"},"answer":"a","keyStatus":"official","marks":2,"negativeMarks":0.6666666666666666,"wordLimit":0,"sourceUrl":"https://iasexamportal.com/ias-pre/papers/upsc-2015-gs-paper-1","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2015-GS-1.pdf#page=3","page":0,"blocks":[{"type":"paragraph","text":"In which of the following activities are Indian Remote Sensing (IRS) satellites used?"},{"type":"paragraph","text":"1. Assessment of crop productivity"},{"type":"paragraph","text":"2. Locating groundwater resources"},{"type":"paragraph","text":"3. Mineral exploration"},{"type":"paragraph","text":"4. Telecommunications"},{"type":"paragraph","text":"5. Traffic studies"},{"type":"paragraph","text":"Select the correct answer using the code given below."}],"sourceTitle":"UPSC CSE 2015 General Studies Paper I · Series C","explanation":{"justification":"India's remote sensing program was developed with the idea of applying space technologies for the benefit of humankind and the development of the country. India's remote sensing programme under the ISRO started off in 1988 with the IRS-1A, the first of the series of indigenous state-of-art operating remote sensing satellites, which was successfully launched into a polar sun-synchronous orbit on March 17, 1988 from the Soviet Cosmodrome at Baikonur. Applications: Space Based Inputs for Decentralized Planning (SIS-DP), National Urban Information System (NUIS), ISRO Disaster Management Support Programme (ISRO-DMSP), Preharvest crop area and production estimation of major crops, Drought monitoring and assessment based on vegetation condition, Flood risk zone mapping and flood damage assessment, Hydro-geomorphological maps for locating underground water resources for drilling well, Irrigation command area status monitoring, Snow-melt run-off estimates for planning water use in down stream projects, Land use and land cover mapping, Urban planning, Forest survey, Wetland mapping, Environmental impact analysis, Mineral Prospecting, Coastal studies. Indian Remote Sensing satellite is not used for telecommunications or in traffic studies and for these, geo-stationary satellite is utilised.","concept":"","references":[]},"sourceNotes":"Editorial study note matched by question wording and the final key’s correct-option wording; the UPSC final key controls scoring."},{"id":"upsc-2015-prelims-gs1-c-022","year":2015,"stage":"Prelims","paper":"Prelims GS-I","number":22,"booklet":"C","questionType":"MCQ","subject":"Geography","topic":"Indian vegetation","question":"Consider the following States\\n\\n1. Arunachal Pradesh\\n\\n2. Himachal Pradesh\\n\\n3. Mizoram\\n\\nIn which of the above States do 'Tropical Wet Evergreen Forests' occur?","options":{"a":"1 only","b":"2 and 3 only","c":"1 and 3 only","d":"1, 2 and 3"},"answer":"c","keyStatus":"official","marks":2,"negativeMarks":0.6666666666666666,"wordLimit":0,"sourceUrl":"https://iasexamportal.com/ias-pre/papers/upsc-2015-gs-paper-1","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2015-GS-1.pdf#page=3","page":0,"blocks":[{"type":"paragraph","text":"Consider the following States"},{"type":"paragraph","text":"1. Arunachal Pradesh"},{"type":"paragraph","text":"2. Himachal Pradesh"},{"type":"paragraph","text":"3. Mizoram"},{"type":"paragraph","text":"In which of the above States do 'Tropical Wet Evergreen Forests' occur?"}],"sourceTitle":"UPSC CSE 2015 General Studies Paper I · Series C","explanation":{"justification":"The warm, humid conditions of Arunachal Pradesh and Mizoram support tropical wet evergreen forests. Himachal Pradesh’s temperate and mountain vegetation does not match this forest type.","concept":"Indian vegetation","references":[{"title":"UPSC CSE2015 final key · SeriesC","url":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2015-GS-1.pdf#page=3"}]},"sourceNotes":"Editorial study note checked against the final key’s correct option; UPSC publishes the answer key, not these explanations."},{"id":"upsc-2015-prelims-gs1-c-023","year":2015,"stage":"Prelims","paper":"Prelims GS-I","number":23,"booklet":"C","questionType":"MCQ","subject":"Science & Technology","topic":"Applied science & technology","question":"The term 'IndARC', sometimes seen in the news, is the name of","options":{"a":"an indigenously developed radar system inducted into Indian Defence","b":"India's satellite to provide services to the countries of Indian Ocean Rim","c":"a scientific establishment set up by India in Antarctic region","d":"India’s underwater observatory to scientifically study the Arctic region"},"answer":"d","keyStatus":"official","marks":2,"negativeMarks":0.6666666666666666,"wordLimit":0,"sourceUrl":"https://iasexamportal.com/ias-pre/papers/upsc-2015-gs-paper-1","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2015-GS-1.pdf#page=3","page":0,"blocks":[{"type":"paragraph","text":"The term 'IndARC', sometimes seen in the news, is the name of"}],"sourceTitle":"UPSC CSE 2015 General Studies Paper I · Series C","explanation":{"justification":"IndARC is India's first underwater observatory in the Arctic region, deployed in 2014 at Svalbard, Norway, to study the Arctic climate and its influence on the monsoon.","concept":"","references":[]},"sourceNotes":"Editorial study note matched by question wording and the final key’s correct-option wording; the UPSC final key controls scoring."},{"id":"upsc-2015-prelims-gs1-c-024","year":2015,"stage":"Prelims","paper":"Prelims GS-I","number":24,"booklet":"C","questionType":"MCQ","subject":"Environment","topic":"Climate action & agreements","question":"With reference to 'Forest Carbon Partnership Facility', which of the following statements is/ are correct?\\n\\n1. It is a global partnership of governments, businesses, civil society and indigenous peoples.\\n\\n2. It provides financial aid to universities, individual scientists and institutions involved in scientific forestry research to develop eco-friendly and climate adaptation technologies for sustainable forest management.\\n\\n3. It assists the countries in their 'REDD+ (Reducing Emissions from Deforestation and Forest Degradation+)' efforts by providing them with financial and technical assistance.\\n\\nSelect the correct answer using the code given below.","options":{"a":"1 only","b":"2 and 3 only","c":"1 and 3 only","d":"1, 2 and 3"},"answer":"c","keyStatus":"official","marks":2,"negativeMarks":0.6666666666666666,"wordLimit":0,"sourceUrl":"https://iasexamportal.com/ias-pre/papers/upsc-2015-gs-paper-1","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2015-GS-1.pdf#page=3","page":0,"blocks":[{"type":"paragraph","text":"With reference to 'Forest Carbon Partnership Facility', which of the following statements is/ are correct?"},{"type":"paragraph","text":"1. It is a global partnership of governments, businesses, civil society and indigenous peoples."},{"type":"paragraph","text":"2. It provides financial aid to universities, individual scientists and institutions involved in scientific forestry research to develop eco-friendly and climate adaptation technologies for sustainable forest management."},{"type":"paragraph","text":"3. It assists the countries in their 'REDD+ (Reducing Emissions from Deforestation and Forest Degradation+)' efforts by providing them with financial and technical assistance."},{"type":"paragraph","text":"Select the correct answer using the code given below."}],"sourceTitle":"UPSC CSE 2015 General Studies Paper I · Series C","explanation":{"justification":"The FCPF is a global partnership focused on reducing emissions from deforestation (REDD+) (Statement 1 is correct) by building the capacity of developing countries through financial and technical assistance (Statement 3 is correct).  It does not exist to provide grants to universities or individual scientists for general forestry research (Statement 2 is incorrect).","concept":"","references":[]},"sourceNotes":"Editorial study note matched by question wording and the final key’s correct-option wording; the UPSC final key controls scoring."},{"id":"upsc-2015-prelims-gs1-c-025","year":2015,"stage":"Prelims","paper":"Prelims GS-I","number":25,"booklet":"C","questionType":"MCQ","subject":"Art & Culture","topic":"Classical languages","question":"Which one of the following was given classical language status recently?","options":{"a":"Odia","b":"Konkani","c":"Bhojpuri","d":"Assamese"},"answer":"a","keyStatus":"official","marks":2,"negativeMarks":0.6666666666666666,"wordLimit":0,"sourceUrl":"https://iasexamportal.com/ias-pre/papers/upsc-2015-gs-paper-1","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2015-GS-1.pdf#page=3","page":0,"blocks":[{"type":"paragraph","text":"Which one of the following was given classical language status recently?"}],"sourceTitle":"UPSC CSE 2015 General Studies Paper I · Series C","explanation":{"justification":"Odia received classical language status in 2014, making it the recent addition relevant to the 2015 question. The answer is evaluated in its examination-year context.","concept":"Classical languages","references":[{"title":"UPSC CSE2015 final key · SeriesC","url":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2015-GS-1.pdf#page=3"}]},"sourceNotes":"Editorial study note checked against the final key’s correct option; UPSC publishes the answer key, not these explanations."},{"id":"upsc-2015-prelims-gs1-c-026","year":2015,"stage":"Prelims","paper":"Prelims GS-I","number":26,"booklet":"C","questionType":"MCQ","subject":"Environment","topic":"Climate action & agreements","question":"With reference to an organization known as ‘Birdlife International’, which of the following statements is/are correct?\\n\\n1. It is a Global Partnership of Conservation Organizations.\\n\\n2. The concept of ‘biodiversity hotspots’ originated from this organization.\\n\\n3. It identifies the sites known/referred to as ‘Important Bird and Biodiversity Areas’.\\n\\nSelect the correct answer using the code given below.","options":{"a":"1 only","b":"2 and 3 only","c":"1 and 3 only","d":"1, 2 and 3"},"answer":"c","keyStatus":"official","marks":2,"negativeMarks":0.6666666666666666,"wordLimit":0,"sourceUrl":"https://iasexamportal.com/ias-pre/papers/upsc-2015-gs-paper-1","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2015-GS-1.pdf#page=3","page":0,"blocks":[{"type":"paragraph","text":"With reference to an organization known as ‘Birdlife International’, which of the following statements is/are correct?"},{"type":"paragraph","text":"1. It is a Global Partnership of Conservation Organizations."},{"type":"paragraph","text":"2. The concept of ‘biodiversity hotspots’ originated from this organization."},{"type":"paragraph","text":"3. It identifies the sites known/referred to as ‘Important Bird and Biodiversity Areas’."},{"type":"paragraph","text":"Select the correct answer using the code given below."}],"sourceTitle":"UPSC CSE 2015 General Studies Paper I · Series C","explanation":{"justification":"BirdLife International is a global partnership of non-governmental conservation organizations (Statement 1 is correct) that actively identifies and monitors a network of sites known as 'Important Bird and Biodiversity Areas' (IBAs) (Statement 3 is correct).  The concept of 'biodiversity hotspots', however, was formulated by British ecologist Norman Myers, not BirdLife International (Statement 2 is incorrect).","concept":"","references":[]},"sourceNotes":"Editorial study note matched by question wording and the final key’s correct-option wording; the UPSC final key controls scoring."},{"id":"upsc-2015-prelims-gs1-c-027","year":2015,"stage":"Prelims","paper":"Prelims GS-I","number":27,"booklet":"C","questionType":"MCQ","subject":"Geography","topic":"World geography & mapping","question":"Which one of the following countries of South-West Asia does not open out to the Mediterranean Sea?","options":{"a":"Syria","b":"Jordan","c":"Lebanon","d":"Israel"},"answer":"b","keyStatus":"official","marks":2,"negativeMarks":0.6666666666666666,"wordLimit":0,"sourceUrl":"https://iasexamportal.com/ias-pre/papers/upsc-2015-gs-paper-1","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2015-GS-1.pdf#page=3","page":0,"blocks":[{"type":"paragraph","text":"Which one of the following countries of South-West Asia does not open out to the Mediterranean Sea?"}],"sourceTitle":"UPSC CSE 2015 General Studies Paper I · Series C","explanation":{"justification":"21 countries including Albania, Algeria, Bosnia and Herzegovina, Croatia, Cyprus, Egypt, France, Greece, Israel, Italy, Lebanon, Libya, Malta, Monaco, Montenegro, Morocco, Slovenia, Spain, Syria, Tunisia, and Turkey share their border with Mediterranean Sea.","concept":"","references":[]},"sourceNotes":"Editorial study note matched by question wording and the final key’s correct-option wording; the UPSC final key controls scoring."},{"id":"upsc-2015-prelims-gs1-c-028","year":2015,"stage":"Prelims","paper":"Prelims GS-I","number":28,"booklet":"C","questionType":"MCQ","subject":"Geography","topic":"India Physical Environment","question":"In India, in which one of the following types of forests is teak a dominant tree species?","options":{"a":"Tropical moist deciduous forest","b":"Tropical rain forest","c":"Tropical thorn scrub forest","d":"Temperate forest with grasslands"},"answer":"a","keyStatus":"official","marks":2,"negativeMarks":0.6666666666666666,"wordLimit":0,"sourceUrl":"https://iasexamportal.com/ias-pre/papers/upsc-2015-gs-paper-1","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2015-GS-1.pdf#page=3","page":0,"blocks":[{"type":"paragraph","text":"In India, in which one of the following types of forests is teak a dominant tree species?"}],"sourceTitle":"UPSC CSE 2015 General Studies Paper I · Series C","explanation":{"justification":"Teak is the most dominant species of Tropical Moist Deciduous Forest. Tropical Deciduous Forest are the most widespread forests of India. They are also called the monsoon forests and spread over the region receiving rainfall between 200 cm and 70 cm. Trees of this forest type shed their leaves for about six to eight weeks in dry summer. On the basis of the availability of water, these forests are further divided into moist and dry deciduous. The former is found in areas receiving rainfall between 200 and 100 cm. These forests exist, therefore, mostly in the eastern part of the country — northeastern states, along the foothills of the Himalayas, Jharkhand, West Odisha and Chhattisgarh, and on the eastern slopes of the Western Ghats. Teak is the most dominant species of this forest. Bamboos, sal, shisham, sandalwood, khair, kusum, arjun and mulberry are other commercially important species.","concept":"India Physical Environment","references":[]},"sourceNotes":"Editorial study note matched by question wording and the final key’s correct-option wording; the UPSC final key controls scoring."},{"id":"upsc-2015-prelims-gs1-c-029","year":2015,"stage":"Prelims","paper":"Prelims GS-I","number":29,"booklet":"C","questionType":"MCQ","subject":"International Relations","topic":"Gender equality","question":"'Beijing Declaration and Platform for Action', often seen in the news, is","options":{"a":"a strategy to tackle the regional terrorism, an outcome of a meeting of the Shanghai Cooperation Organization","b":"a plan of action for sustainable economic growth in the Asia-Pacific Region, an outcome of the deliberations of the Asia-Pacific Economic Forum","c":"an agenda for women's empowerment, an outcome of a World Conference convened by the United Nations","d":"a strategy to combat wildlife trafficking, a declaration of the East Asia Summit"},"answer":"c","keyStatus":"official","marks":2,"negativeMarks":0.6666666666666666,"wordLimit":0,"sourceUrl":"https://iasexamportal.com/ias-pre/papers/upsc-2015-gs-paper-1","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2015-GS-1.pdf#page=3","page":0,"blocks":[{"type":"paragraph","text":"'Beijing Declaration and Platform for Action', often seen in the news, is"}],"sourceTitle":"UPSC CSE 2015 General Studies Paper I · Series C","explanation":{"justification":"The 1995 United Nations Fourth World Conference on Women adopted the Beijing Declaration and Platform for Action. Its agenda concerns women’s rights, equality and empowerment.","concept":"Gender equality","references":[{"title":"UPSC CSE2015 final key · SeriesC","url":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2015-GS-1.pdf#page=3"}]},"sourceNotes":"Editorial study note checked against the final key’s correct option; UPSC publishes the answer key, not these explanations."},{"id":"upsc-2015-prelims-gs1-c-030","year":2015,"stage":"Prelims","paper":"Prelims GS-I","number":30,"booklet":"C","questionType":"MCQ","subject":"Geography","topic":"Climatology","question":"\\"Each day is more or less the same, the morning is clear and bright with a sea breeze; as the Sun climbs high in the sky, heat mounts up, dark clouds form, then rain comes with thunder and lightning. But rain is soon over.\\" Which of the following regions is described in the above passage?","options":{"a":"Savannah","b":"Equatorial","c":"Monsoon","d":"Mediterranean"},"answer":"b","keyStatus":"official","marks":2,"negativeMarks":0.6666666666666666,"wordLimit":0,"sourceUrl":"https://iasexamportal.com/ias-pre/papers/upsc-2015-gs-paper-1","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2015-GS-1.pdf#page=3","page":0,"blocks":[{"type":"paragraph","text":"\\"Each day is more or less the same, the morning is clear and bright with a sea breeze; as the Sun climbs high in the sky, heat mounts up, dark clouds form, then rain comes with thunder and lightning. But rain is soon over.\\" Which of the following regions is described in the above passage?"}],"sourceTitle":"UPSC CSE 2015 General Studies Paper I · Series C","explanation":{"justification":"This is the characteristic description of the Equatorial climate (tropical rainforest climate), which experiences hot, humid weather and daily convectional rainfall with thunderstorms in the afternoon.","concept":"","references":[]},"sourceNotes":"Editorial study note matched by question wording and the final key’s correct-option wording; the UPSC final key controls scoring."},{"id":"upsc-2015-prelims-gs1-c-031","year":2015,"stage":"Prelims","paper":"Prelims GS-I","number":31,"booklet":"C","questionType":"MCQ","subject":"Economy","topic":"GDP levels and growth rates","question":"With reference to Indian economy, consider the following statements:\\n\\n1. The rate of growth of Real Gross Domestic Product has steadily increased in the last decade.\\n\\n2. The Gross Domestic Product at market prices (in rupees) has steadily increased in the last\\n\\ndecade.\\n\\nWhich of the statements given above is/are correct?","options":{"a":"1 only","b":"2 only","c":"Both 1 and 2","d":"Neither 1 nor 2"},"answer":"b","keyStatus":"official","marks":2,"negativeMarks":0.6666666666666666,"wordLimit":0,"sourceUrl":"https://iasexamportal.com/ias-pre/papers/upsc-2015-gs-paper-1","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2015-GS-1.pdf#page=3","page":0,"blocks":[{"type":"paragraph","text":"With reference to Indian economy, consider the following statements:"},{"type":"paragraph","text":"1. The rate of growth of Real Gross Domestic Product has steadily increased in the last decade."},{"type":"paragraph","text":"2. The Gross Domestic Product at market prices (in rupees) has steadily increased in the last\\n\\ndecade."},{"type":"paragraph","text":"Which of the statements given above is/are correct?"}],"sourceTitle":"UPSC CSE 2015 General Studies Paper I · Series C","explanation":{"justification":"The rupee value of GDP at market prices increased over the preceding decade, but the real GDP growth rate fluctuated. An increasing level of output does not imply a continuously rising growth rate.","concept":"GDP levels and growth rates","references":[{"title":"UPSC CSE2015 final key · SeriesC","url":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2015-GS-1.pdf#page=3"}]},"sourceNotes":"Editorial study note checked against the final key’s correct option; UPSC publishes the answer key, not these explanations."},{"id":"upsc-2015-prelims-gs1-c-032","year":2015,"stage":"Prelims","paper":"Prelims GS-I","number":32,"booklet":"C","questionType":"MCQ","subject":"Polity & Governance","topic":"Parliament & state legislatures","question":"Consider the following statements :\\n\\n1. The Legislative Council of a State in India can be larger in size than half of the Legislative Assembly of that particular State\\n\\n2. The Governor of a State nominates the Chairman of Legislative Council of that particular State.\\n\\nWhich of the statements given above is/are correct?","options":{"a":"1 only","b":"2 only","c":"Both 1 and 2","d":"Neither 1 nor 2"},"answer":"d","keyStatus":"official","marks":2,"negativeMarks":0.6666666666666666,"wordLimit":0,"sourceUrl":"https://iasexamportal.com/ias-pre/papers/upsc-2015-gs-paper-1","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2015-GS-1.pdf#page=3","page":0,"blocks":[{"type":"paragraph","text":"Consider the following statements :"},{"type":"paragraph","text":"1. The Legislative Council of a State in India can be larger in size than half of the Legislative Assembly of that particular State"},{"type":"paragraph","text":"2. The Governor of a State nominates the Chairman of Legislative Council of that particular State."},{"type":"paragraph","text":"Which of the statements given above is/are correct?"}],"sourceTitle":"UPSC CSE 2015 General Studies Paper I · Series C","explanation":{"justification":"The maximum strength of a Legislative Council is fixed at one-third of the Legislative Assembly, not half (Statement 1 is incorrect). The Chairman is elected by the council itself from amongst its members, not nominated by the Governor (Statement 2 is incorrect).","concept":"","references":[]},"sourceNotes":"Editorial study note matched by question wording and the final key’s correct-option wording; the UPSC final key controls scoring."},{"id":"upsc-2015-prelims-gs1-c-033","year":2015,"stage":"Prelims","paper":"Prelims GS-I","number":33,"booklet":"C","questionType":"MCQ","subject":"Polity & Governance","topic":"Fundamental Duties","question":"\\"To uphold and protect the Sovereignty, Unity and Integrity of India\\" is a provision made in the","options":{"a":"Preamble of the Constitution","b":"Directive Principles of State Policy","c":"Fundamental Rights","d":"Fundamental Duties"},"answer":"d","keyStatus":"official","marks":2,"negativeMarks":0.6666666666666666,"wordLimit":0,"sourceUrl":"https://iasexamportal.com/ias-pre/papers/upsc-2015-gs-paper-1","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2015-GS-1.pdf#page=3","page":0,"blocks":[{"type":"paragraph","text":"\\"To uphold and protect the Sovereignty, Unity and Integrity of India\\" is a provision made in the"}],"sourceTitle":"UPSC CSE 2015 General Studies Paper I · Series C","explanation":{"justification":"Article 51A(c) makes upholding and protecting India’s sovereignty, unity and integrity a Fundamental Duty. The wording is from the duties in Part IVA.","concept":"Fundamental Duties","references":[{"title":"UPSC CSE2015 final key · SeriesC","url":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2015-GS-1.pdf#page=3"}]},"sourceNotes":"Editorial study note checked against the final key’s correct option; UPSC publishes the answer key, not these explanations."},{"id":"upsc-2015-prelims-gs1-c-034","year":2015,"stage":"Prelims","paper":"Prelims GS-I","number":34,"booklet":"C","questionType":"MCQ","subject":"Environment","topic":"Ecology & environment","question":"Which one of the following is the best description of the term 'ecosystem'?","options":{"a":"A community of organisms interacting with one another.","b":"That part of the Earth which is inhabited by living organisms.","c":"A community of organisms together with the environment in which they live","d":"The flora and fauna of a geographical area"},"answer":"c","keyStatus":"official","marks":2,"negativeMarks":0.6666666666666666,"wordLimit":0,"sourceUrl":"https://iasexamportal.com/ias-pre/papers/upsc-2015-gs-paper-1","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2015-GS-1.pdf#page=3","page":0,"blocks":[{"type":"paragraph","text":"Which one of the following is the best description of the term 'ecosystem'?"}],"sourceTitle":"UPSC CSE 2015 General Studies Paper I · Series C","explanation":{"justification":"An ecosystem is a community of living organisms (biotic components) interacting in conjunction with the non-living components (abiotic components) of their physical environment.","concept":"","references":[]},"sourceNotes":"Editorial study note matched by question wording and the final key’s correct-option wording; the UPSC final key controls scoring."},{"id":"upsc-2015-prelims-gs1-c-035","year":2015,"stage":"Prelims","paper":"Prelims GS-I","number":35,"booklet":"C","questionType":"MCQ","subject":"Polity & Governance","topic":"Local government","question":"The fundamental object of Panchayati Raj system is to ensure which among the following?\\n\\n1. People's participation in development\\n\\n2. Political accountability\\n\\n3. Democratic decentralization\\n\\n4. Financial mobilization\\n\\nSelect the correct answer using the code given below.","options":{"a":"1, 2 and 3 only","b":"2 and 4 only","c":"1 and 3 only","d":"1, 2, 3 and 4"},"answer":"c","keyStatus":"official","marks":2,"negativeMarks":0.6666666666666666,"wordLimit":0,"sourceUrl":"https://iasexamportal.com/ias-pre/papers/upsc-2015-gs-paper-1","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2015-GS-1.pdf#page=3","page":0,"blocks":[{"type":"paragraph","text":"The fundamental object of Panchayati Raj system is to ensure which among the following?"},{"type":"paragraph","text":"1. People's participation in development"},{"type":"paragraph","text":"2. Political accountability"},{"type":"paragraph","text":"3. Democratic decentralization"},{"type":"paragraph","text":"4. Financial mobilization"},{"type":"paragraph","text":"Select the correct answer using the code given below."}],"sourceTitle":"UPSC CSE 2015 General Studies Paper I · Series C","explanation":{"justification":"The fundamental object of the Panchayati Raj system is to ensure people's participation in governance and development, leading to democratic decentralization. It was not established for political accountability (which already existed via state legislatures) or financial mobilization.","concept":"","references":[]},"sourceNotes":"Editorial study note matched by question wording and the final key’s correct-option wording; the UPSC final key controls scoring."},{"id":"upsc-2015-prelims-gs1-c-036","year":2015,"stage":"Prelims","paper":"Prelims GS-I","number":36,"booklet":"C","questionType":"MCQ","subject":"Economy","topic":"Banking, money & financial markets","question":"With reference to Indian economy, consider the following\\n\\n1. Bank rate\\n\\n2. Open market operations\\n\\n3. Public debt\\n\\n4. Public revenue\\n\\nWhich of the above is/are component/ components of Monetary Policy?","options":{"a":"1 only","b":"2, 3 and 4","c":"1 and 2","d":"1, 3 and 4"},"answer":"c","keyStatus":"official","marks":2,"negativeMarks":0.6666666666666666,"wordLimit":0,"sourceUrl":"https://iasexamportal.com/ias-pre/papers/upsc-2015-gs-paper-1","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2015-GS-1.pdf#page=3","page":0,"blocks":[{"type":"paragraph","text":"With reference to Indian economy, consider the following"},{"type":"paragraph","text":"1. Bank rate"},{"type":"paragraph","text":"2. Open market operations"},{"type":"paragraph","text":"3. Public debt"},{"type":"paragraph","text":"4. Public revenue"},{"type":"paragraph","text":"Which of the above is/are component/ components of Monetary Policy?"}],"sourceTitle":"UPSC CSE 2015 General Studies Paper I · Series C","explanation":{"justification":"Bank Rate and Open Market Operations (OMOs), along with CRR, SLR, and Repo rates, are core instruments of Monetary Policy managed by the RBI to regulate money supply, interest rates, and liquidity. Public debt and public revenue (taxation and spending) are components of Fiscal Policy managed by the government.","concept":"","references":[]},"sourceNotes":"Editorial study note matched by question wording and the final key’s correct-option wording; the UPSC final key controls scoring."},{"id":"upsc-2015-prelims-gs1-c-037","year":2015,"stage":"Prelims","paper":"Prelims GS-I","number":37,"booklet":"C","questionType":"MCQ","subject":"Economy","topic":"Banking, money & financial markets","question":"With reference to inflation in India, which of the following statements is correct?","options":{"a":"Controlling the inflation in India is the responsibility of the Government of India only","b":"The Reserve Bank of India has no role in controlling the inflation","c":"Decreased money circulation helps in controlling the inflation","d":"Increased money circulation helps in controlling the inflation"},"answer":"c","keyStatus":"official","marks":2,"negativeMarks":0.6666666666666666,"wordLimit":0,"sourceUrl":"https://iasexamportal.com/ias-pre/papers/upsc-2015-gs-paper-1","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2015-GS-1.pdf#page=3","page":0,"blocks":[{"type":"paragraph","text":"With reference to inflation in India, which of the following statements is correct?"}],"sourceTitle":"UPSC CSE 2015 General Studies Paper I · Series C","explanation":{"justification":"Inflation is caused when excess money supply chases limited goods and services. When the RBI implements a tight or contractionary monetary policy to decrease money circulation in the economy, it reduces aggregate consumer purchasing power and demand, which effectively checks and controls inflation.","concept":"","references":[]},"sourceNotes":"Editorial study note matched by question wording and the final key’s correct-option wording; the UPSC final key controls scoring."},{"id":"upsc-2015-prelims-gs1-c-038","year":2015,"stage":"Prelims","paper":"Prelims GS-I","number":38,"booklet":"C","questionType":"MCQ","subject":"International Relations","topic":"Nuclear Non-Proliferation Treaty","question":"Consider the following countries\\n\\n1. China\\n\\n2. France\\n\\n3. India\\n\\n4. Israel\\n\\n5. Pakistan\\n\\nWhich among the above are Nuclear Weapons States as recognized by the Treaty on the Non-Proliferation of Nuclear Weapons, commonly known as Nuclear Non-Proliferation Treaty (NPT)?","options":{"a":"1 and 2 only","b":"1, 3, 4 and 5 only","c":"2, 4 and 5 only","d":"1, 2, 3, 4 and 5"},"answer":"a","keyStatus":"official","marks":2,"negativeMarks":0.6666666666666666,"wordLimit":0,"sourceUrl":"https://iasexamportal.com/ias-pre/papers/upsc-2015-gs-paper-1","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2015-GS-1.pdf#page=3","page":0,"blocks":[{"type":"paragraph","text":"Consider the following countries"},{"type":"paragraph","text":"1. China"},{"type":"paragraph","text":"2. France"},{"type":"paragraph","text":"3. India"},{"type":"paragraph","text":"4. Israel"},{"type":"paragraph","text":"5. Pakistan"},{"type":"paragraph","text":"Which among the above are Nuclear Weapons States as recognized by the Treaty on the Non-Proliferation of Nuclear Weapons, commonly known as Nuclear Non-Proliferation Treaty (NPT)?"}],"sourceTitle":"UPSC CSE 2015 General Studies Paper I · Series C","explanation":{"justification":"The NPT recognises the United States, Russia, United Kingdom, France and China as nuclear-weapon States. Of the listed countries only China and France fall in that category.","concept":"Nuclear Non-Proliferation Treaty","references":[{"title":"UPSC CSE2015 final key · SeriesC","url":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2015-GS-1.pdf#page=3"}]},"sourceNotes":"Editorial study note checked against the final key’s correct option; UPSC publishes the answer key, not these explanations."},{"id":"upsc-2015-prelims-gs1-c-039","year":2015,"stage":"Prelims","paper":"Prelims GS-I","number":39,"booklet":"C","questionType":"MCQ","subject":"Polity & Governance","topic":"Rights, duties & directive principles","question":"The ideal of Welfare State' in the Indian Constitution is enshrined in its","options":{"a":"Preamble","b":"Directive Principles of State Policy","c":"Fundamental Rights","d":"Seventh Schedule"},"answer":"b","keyStatus":"official","marks":2,"negativeMarks":0.6666666666666666,"wordLimit":0,"sourceUrl":"https://iasexamportal.com/ias-pre/papers/upsc-2015-gs-paper-1","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2015-GS-1.pdf#page=3","page":0,"blocks":[{"type":"paragraph","text":"The ideal of Welfare State' in the Indian Constitution is enshrined in its"}],"sourceTitle":"UPSC CSE 2015 General Studies Paper I · Series C","explanation":{"justification":"Part IV of the Constitution (Directive Principles of State Policy) aims at ensuring socio-economic justice and embodies the concept of a 'welfare state' rather than a police state.","concept":"","references":[]},"sourceNotes":"Editorial study note matched by question wording and the final key’s correct-option wording; the UPSC final key controls scoring."},{"id":"upsc-2015-prelims-gs1-c-040","year":2015,"stage":"Prelims","paper":"Prelims GS-I","number":40,"booklet":"C","questionType":"MCQ","subject":"Economy","topic":"Agriculture & allied sectors","question":"The substitution of steel for wooden ploughs in agricultural production is an example of","options":{"a":"labour-augmenting technological progress","b":"capital-augmenting technological progress","c":"capital-reducing technological progress","d":"None of the above"},"answer":"b","keyStatus":"official","marks":2,"negativeMarks":0.6666666666666666,"wordLimit":0,"sourceUrl":"https://iasexamportal.com/ias-pre/papers/upsc-2015-gs-paper-1","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2015-GS-1.pdf#page=3","page":0,"blocks":[{"type":"paragraph","text":"The substitution of steel for wooden ploughs in agricultural production is an example of"}],"sourceTitle":"UPSC CSE 2015 General Studies Paper I · Series C","explanation":{"justification":"Replacing a wooden plow with a more durable, efficient steel plow represents an improvement in the quality and productivity of an existing physical capital asset (the tool). In economics, technological progress that enhances the efficiency of capital goods is termed \\"capital-augmenting\\".","concept":"","references":[]},"sourceNotes":"Editorial study note matched by question wording and the final key’s correct-option wording; the UPSC final key controls scoring."},{"id":"upsc-2015-prelims-gs1-c-041","year":2015,"stage":"Prelims","paper":"Prelims GS-I","number":41,"booklet":"C","questionType":"MCQ","subject":"Polity & Governance","topic":"Parliamentary government","question":"There is a Parliamentary System of Government in India because the","options":{"a":"Lok Sabha is elected directly by the people","b":"Parliament can amend the Constitution","c":"Rajya Sabha cannot be dissolved","d":"Council of Ministers is responsible to the Lok Sabha"},"answer":"d","keyStatus":"official","marks":2,"negativeMarks":0.6666666666666666,"wordLimit":0,"sourceUrl":"https://iasexamportal.com/ias-pre/papers/upsc-2015-gs-paper-1","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2015-GS-1.pdf#page=3","page":0,"blocks":[{"type":"paragraph","text":"There is a Parliamentary System of Government in India because the"}],"sourceTitle":"UPSC CSE 2015 General Studies Paper I · Series C","explanation":{"justification":"Article 75(3) makes the Council of Ministers collectively responsible to the Lok Sabha. This responsibility of the executive to the legislature is the defining parliamentary feature.","concept":"Parliamentary government","references":[{"title":"UPSC CSE2015 final key · SeriesC","url":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2015-GS-1.pdf#page=3"}]},"sourceNotes":"Editorial study note checked against the final key’s correct option; UPSC publishes the answer key, not these explanations."},{"id":"upsc-2015-prelims-gs1-c-042","year":2015,"stage":"Prelims","paper":"Prelims GS-I","number":42,"booklet":"C","questionType":"MCQ","subject":"Science & Technology","topic":"Applied science & technology","question":"H1N1 virus is sometimes mentioned in the news with reference to which one of the following diseases?","options":{"a":"AIDS","b":"Bird flu","c":"Dengue","d":"Swine flu"},"answer":"d","keyStatus":"official","marks":2,"negativeMarks":0.6666666666666666,"wordLimit":0,"sourceUrl":"https://iasexamportal.com/ias-pre/papers/upsc-2015-gs-paper-1","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2015-GS-1.pdf#page=3","page":0,"blocks":[{"type":"paragraph","text":"H1N1 virus is sometimes mentioned in the news with reference to which one of the following diseases?"}],"sourceTitle":"UPSC CSE 2015 General Studies Paper I · Series C","explanation":{"justification":"Swine flu is a type of influenza A virus, specifically the H1N1 strain, that infects pigs, birds, and humans, and was declared a pandemic in 2009.","concept":"","references":[]},"sourceNotes":"Editorial study note matched by question wording and the final key’s correct-option wording; the UPSC final key controls scoring."},{"id":"upsc-2015-prelims-gs1-c-043","year":2015,"stage":"Prelims","paper":"Prelims GS-I","number":43,"booklet":"C","questionType":"MCQ","subject":"Science & Technology","topic":"Applied science & technology","question":"With reference to bio-toilets used by the Indian Railways, consider the following statements:\\n\\n1.The decomposition of human waste in the bio-toilets is initiated by a fungal inoculum.\\n\\n2. Ammonia and water vapour are the only end products in this decomposition which are released into the atmosphere.\\n\\nWhich of the statements given above is/are correct?","options":{"a":"1 only","b":"2 only","c":"Both 1 and 2","d":"Neither 1 nor 2"},"answer":"d","keyStatus":"official","marks":2,"negativeMarks":0.6666666666666666,"wordLimit":0,"sourceUrl":"https://iasexamportal.com/ias-pre/papers/upsc-2015-gs-paper-1","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2015-GS-1.pdf#page=3","page":0,"blocks":[{"type":"paragraph","text":"With reference to bio-toilets used by the Indian Railways, consider the following statements:"},{"type":"paragraph","text":"1.The decomposition of human waste in the bio-toilets is initiated by a fungal inoculum."},{"type":"paragraph","text":"2. Ammonia and water vapour are the only end products in this decomposition which are released into the atmosphere."},{"type":"paragraph","text":"Which of the statements given above is/are correct?"}],"sourceTitle":"UPSC CSE 2015 General Studies Paper I · Series C","explanation":{"justification":"The decomposition in bio-toilets is carried out by anaerobic bacteria, not a fungal inoculum. The end products are primarily colorless, odorless water and highly inflammable Methane gas, not just ammonia and water vapor. Therefore, both statements are incorrect.","concept":"","references":[]},"sourceNotes":"Editorial study note matched by question wording and the final key’s correct-option wording; the UPSC final key controls scoring."},{"id":"upsc-2015-prelims-gs1-c-044","year":2015,"stage":"Prelims","paper":"Prelims GS-I","number":44,"booklet":"C","questionType":"MCQ","subject":"Economy","topic":"International trade & institutions","question":"The problem of international liquidity is related to the non-availability of","options":{"a":"goods and services","b":"gold and silver","c":"dollars and other hard currencies","d":"exportable surplus"},"answer":"c","keyStatus":"official","marks":2,"negativeMarks":0.6666666666666666,"wordLimit":0,"sourceUrl":"https://iasexamportal.com/ias-pre/papers/upsc-2015-gs-paper-1","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2015-GS-1.pdf#page=3","page":0,"blocks":[{"type":"paragraph","text":"The problem of international liquidity is related to the non-availability of"}],"sourceTitle":"UPSC CSE 2015 General Studies Paper I · Series C","explanation":{"justification":"International liquidity refers to the resources available to national monetary authorities to finance balance of payments deficits. Therefore, the problem of international liquidity arises directly from the non-availability of universally acceptable assets like US dollars, other hard foreign currencies, SDRs, or gold stocks.","concept":"","references":[]},"sourceNotes":"Editorial study note matched by question wording and the final key’s correct-option wording; the UPSC final key controls scoring."},{"id":"upsc-2015-prelims-gs1-c-045","year":2015,"stage":"Prelims","paper":"Prelims GS-I","number":45,"booklet":"C","questionType":"MCQ","subject":"Science & Technology","topic":"Applied science & technology","question":"With reference to 'fuel cells' in which hydrogen-rich fuel and oxygen are used to generate electricity. Consider the following statements :\\n\\n1. If pure hydrogen is used as a fuel, the fuel cell emits heat and water as by-products.\\n\\n2. Fuel cells can be used for powering buildings and not for small devices like laptop computers.\\n\\n3. Fuel cells produce electricity in the form of Alternating Current (AC).\\n\\nWhich of the statements given above is / are correct?","options":{"a":"1 only","b":"2 and 3 only","c":"1 and 3 only","d":"1, 2 and 3"},"answer":"a","keyStatus":"official","marks":2,"negativeMarks":0.6666666666666666,"wordLimit":0,"sourceUrl":"https://iasexamportal.com/ias-pre/papers/upsc-2015-gs-paper-1","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2015-GS-1.pdf#page=3","page":0,"blocks":[{"type":"paragraph","text":"With reference to 'fuel cells' in which hydrogen-rich fuel and oxygen are used to generate electricity. Consider the following statements :"},{"type":"paragraph","text":"1. If pure hydrogen is used as a fuel, the fuel cell emits heat and water as by-products."},{"type":"paragraph","text":"2. Fuel cells can be used for powering buildings and not for small devices like laptop computers."},{"type":"paragraph","text":"3. Fuel cells produce electricity in the form of Alternating Current (AC).\\n\\nWhich of the statements given above is / are correct?"}],"sourceTitle":"UPSC CSE 2015 General Studies Paper I · Series C","explanation":{"justification":"When pure hydrogen is used in a fuel cell, the only by-products are water and heat (Statement 1 is correct). Fuel cells produce Direct Current (DC), not AC, and they can be used for powering both large buildings and small devices like laptops/cell phones (Statements 2 and 3 are incorrect).","concept":"","references":[]},"sourceNotes":"Editorial study note matched by question wording and the final key’s correct-option wording; the UPSC final key controls scoring."},{"id":"upsc-2015-prelims-gs1-c-046","year":2015,"stage":"Prelims","paper":"Prelims GS-I","number":46,"booklet":"C","questionType":"MCQ","subject":"Art & Culture","topic":"Art, architecture & monuments","question":"Kalamkari painting refers to","options":{"a":"a hand-painted cotton textile in South India","b":"a handmade drawing on bamboo handicrafts in North-East India","c":"a block-painted woollen cloth in Western Himalayan region of India","d":"a hand-painted decorative silk cloth in North-Western India"},"answer":"a","keyStatus":"official","marks":2,"negativeMarks":0.6666666666666666,"wordLimit":0,"sourceUrl":"https://iasexamportal.com/ias-pre/papers/upsc-2015-gs-paper-1","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2015-GS-1.pdf#page=3","page":0,"blocks":[{"type":"paragraph","text":"Kalamkari painting refers to"}],"sourceTitle":"UPSC CSE 2015 General Studies Paper I · Series C","explanation":{"justification":"Kalamkari refers to an ancient style of hand-painting or block-printing on cotton textiles produced in Andhra Pradesh and Telangana (South India), using natural vegetable dyes and a kalam (pen).","concept":"","references":[]},"sourceNotes":"Editorial study note matched by question wording and the final key’s correct-option wording; the UPSC final key controls scoring."},{"id":"upsc-2015-prelims-gs1-c-047","year":2015,"stage":"Prelims","paper":"Prelims GS-I","number":47,"booklet":"C","questionType":"MCQ","subject":"Economy","topic":"Agriculture & allied sectors","question":"Which one of the following best describes the main objective of 'Seed Village Concept'?","options":{"a":"Encouraging the farmers to use their own farm seeds and discouraging them to buy the seeds from others","b":"Involving the farmers for training in quality seed production and thereby to make available quality seeds to others at appropriate time and affordable cost","c":"Earmarking some villages exclusively for the production of certified seeds","d":"Identifying the entrepreneurs in village and providing them technology and finance to set up seed companies"},"answer":"b","keyStatus":"official","marks":2,"negativeMarks":0.6666666666666666,"wordLimit":0,"sourceUrl":"https://iasexamportal.com/ias-pre/papers/upsc-2015-gs-paper-1","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2015-GS-1.pdf#page=3","page":0,"blocks":[{"type":"paragraph","text":"Which one of the following best describes the main objective of 'Seed Village Concept'?"}],"sourceTitle":"UPSC CSE 2015 General Studies Paper I · Series C","explanation":{"justification":"The main objective of the 'Seed Village Concept' is to involve farmers in quality seed production through training, empowering them to produce and make quality seeds available to themselves and neighboring farmers at the right time and affordable cost.","concept":"","references":[]},"sourceNotes":"Editorial study note matched by question wording and the final key’s correct-option wording; the UPSC final key controls scoring."},{"id":"upsc-2015-prelims-gs1-c-048","year":2015,"stage":"Prelims","paper":"Prelims GS-I","number":48,"booklet":"C","questionType":"MCQ","subject":"Economy","topic":"Public finance & fiscal policy","question":"There has been a persistent deficit budget year after year. Which of the following actions can be taken by the government to reduce the deficit?\\n\\n1. Reducing revenue expenditure\\n\\n2. Introducing new welfare schemes\\n\\n3. Rationalizing subsidies\\n\\n4. Expanding industries\\n\\nSelect the correct answer using the code given below.","options":{"a":"1 and 3 only","b":"2 and 3 only","c":"1 only","d":"1,2,3 and 4"},"answer":"a","keyStatus":"official","marks":2,"negativeMarks":0.6666666666666666,"wordLimit":0,"sourceUrl":"https://iasexamportal.com/ias-pre/papers/upsc-2015-gs-paper-1","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2015-GS-1.pdf#page=3","page":0,"blocks":[{"type":"paragraph","text":"There has been a persistent deficit budget year after year. Which of the following actions can be taken by the government to reduce the deficit?"},{"type":"paragraph","text":"1. Reducing revenue expenditure"},{"type":"paragraph","text":"2. Introducing new welfare schemes"},{"type":"paragraph","text":"3. Rationalizing subsidies"},{"type":"paragraph","text":"4. Expanding industries"},{"type":"paragraph","text":"Select the correct answer using the code given below."}],"sourceTitle":"UPSC CSE 2015 General Studies Paper I · Series C","explanation":{"justification":"To control a persistent deficit, the government must curtail non-productive outflows by reducing revenue expenditure and rationalizing subsidies. Introducing new welfare schemes or directly funding industrial expansion increases short-term expenditure and worsens the fiscal deficit.","concept":"","references":[]},"sourceNotes":"Editorial study note matched by question wording and the final key’s correct-option wording; the UPSC final key controls scoring."},{"id":"upsc-2015-prelims-gs1-c-049","year":2015,"stage":"Prelims","paper":"Prelims GS-I","number":49,"booklet":"C","questionType":"MCQ","subject":"Economy","topic":"Geographical indications","question":"Which of the following has/have been accorded 'Geographical Indication' status?\\n\\n1. Banaras Brocades and Sarees\\n\\n2. Rajasthani Daal-Bati-Churma\\n\\n3. Tirupathi Laddu\\n\\nSelect the correct answer using the code given below.","options":{"a":"1 only","b":"2 and 3 only","c":"1 and 3 only","d":"1, 2 and 3"},"answer":"c","keyStatus":"official","marks":2,"negativeMarks":0.6666666666666666,"wordLimit":0,"sourceUrl":"https://iasexamportal.com/ias-pre/papers/upsc-2015-gs-paper-1","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2015-GS-1.pdf#page=3","page":0,"blocks":[{"type":"paragraph","text":"Which of the following has/have been accorded 'Geographical Indication' status?"},{"type":"paragraph","text":"1. Banaras Brocades and Sarees"},{"type":"paragraph","text":"2. Rajasthani Daal-Bati-Churma"},{"type":"paragraph","text":"3. Tirupathi Laddu"},{"type":"paragraph","text":"Select the correct answer using the code given below."}],"sourceTitle":"UPSC CSE 2015 General Studies Paper I · Series C","explanation":{"justification":"Banaras Brocades and Sarees and Tirupathi Laddu held GI registrations relevant to the 2015 paper. Rajasthani Daal-Bati-Churma did not, so items 1 and 3 are selected.","concept":"Geographical indications","references":[{"title":"UPSC CSE2015 final key · SeriesC","url":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2015-GS-1.pdf#page=3"}]},"sourceNotes":"Editorial study note checked against the final key’s correct option; UPSC publishes the answer key, not these explanations."},{"id":"upsc-2015-prelims-gs1-c-050","year":2015,"stage":"Prelims","paper":"Prelims GS-I","number":50,"booklet":"C","questionType":"MCQ","subject":"Economy","topic":"Renewable-energy finance","question":"With reference to the Indian Renewable Energy Development Agency Limited (IREDA), which of the following statements is/are correct?\\n\\n1. It is a Public Limited Government Company.\\n\\n2. It is a Non - Banking Financial Company.\\n\\nSelect the correct answer using the code given below.","options":{"a":"1 only","b":"2 only","c":"Both 1 and 2","d":"Neither 1 or 2"},"answer":"c","keyStatus":"official","marks":2,"negativeMarks":0.6666666666666666,"wordLimit":0,"sourceUrl":"https://iasexamportal.com/ias-pre/papers/upsc-2015-gs-paper-1","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2015-GS-1.pdf#page=3","page":0,"blocks":[{"type":"paragraph","text":"With reference to the Indian Renewable Energy Development Agency Limited (IREDA), which of the following statements is/are correct?"},{"type":"paragraph","text":"1. It is a Public Limited Government Company."},{"type":"paragraph","text":"2. It is a Non - Banking Financial Company."},{"type":"paragraph","text":"Select the correct answer using the code given below."}],"sourceTitle":"UPSC CSE 2015 General Studies Paper I · Series C","explanation":{"justification":"IREDA is a Government public limited company that finances renewable energy and is registered as a non-banking financial company. Both descriptions are correct.","concept":"Renewable-energy finance","references":[{"title":"UPSC CSE2015 final key · SeriesC","url":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2015-GS-1.pdf#page=3"}]},"sourceNotes":"Editorial study note checked against the final key’s correct option; UPSC publishes the answer key, not these explanations."}]`);export{e as p};
